-- AI-GENERATED by Zy.AI 1.0.0
-- goal=advance_ui phase_hint=running
-- RULES: Zy.* only; no fixed physical coords; no SDK bypass
-- pipeline: Device>Screen>Coordinate>Vision>OCR>Image>Touch>Verify>StateMachine>Game>Script
_G.__ZIYAN_OCR_NO_SHOT = true

local function ailog(msg)
  print(tostring(msg))
end

function main()
  if type(Zy) ~= "table" then require("modules") end
  local BID = "com.xztl.ios"
  local DW, DH = 1136, 640
  Zy.Device.refresh()
  Zy.Script.begin({ bid = BID, design_w = DW, design_h = DH, orient = 1 })
  Zy.Coordinate.setDesign(DW, DH)
  local prof = Zy.Device.profile()
  ailog("AI script device=" .. tostring(prof and prof.model))
  Zy.App.launch(BID, 800)
  Zy.Screen.sync(1, BID)
  local si = Zy.Screen.info()
  local sw = (si and (si.logic_w or si.w)) or select(1, Zy.Screen.size())
  local sh = (si and (si.logic_h or si.h)) or select(2, Zy.Screen.size())
  ailog("AI screen=" .. tostring(sw) .. "x" .. tostring(sh))
  Zy.Script.set("goal", "advance_ui")

  local handlers = {
    boot = function(ctx) Zy.App.launch(BID, 600); Zy.Screen.sync(1, BID) end,
    loading = function(ctx) end,
    login = function(ctx)
      ctx.tapRatio(0.6048, 0.7562)
    end,
    menu = function(ctx) ctx.tapRatio(0.50, 0.70) end,
    role = function(ctx) ctx.tapRatio(0.50, 0.75) end,
    running = function(ctx) Zy.Script.set("done", true) end,
    error = function(ctx) Zy.Script.recover({ policy = "resync", reason = "ai_error_state" }) end,
    default = function(ctx)
      ctx.tapRatio(0.6048, 0.7562)
    end,
  }

  -- 视觉增强：完整模式 Vision/OCR；冒烟模式直接比例点击（禁止固定物理坐标）
  Zy.Script.defineTask("vision_try", function()
    if _G.__ZIYAN_OCR_NO_SHOT then return false, "smoke_skip_vision" end
    local hit, kind, x, y = Zy.Vision.analyze({
      words = { "登录", "开始", "确定", "进入" }, design_w = DW, design_h = DH,
    })
    if hit and x and x ~= -1 then
      return Zy.Script.act("ai_vision_hit", function(ctx) ctx.tapHit(x, y) end, 300)
    end
    return false, "no_vision_hit"
  end)

  Zy.Script.loop(1, function(i, ctx)
    Zy.Screen.sync(1, BID)
    local st = Zy.StateMachine.current(BID)
    local fr = Zy.Game.analyze(BID, { light = true })
    ailog(string.format("AI loop %d phase=%s st=%s suggest=%s", i, tostring(fr.phase), tostring(st), Zy.Game.suggest(fr.phase)))
    if fr.phase == "running" then Zy.Script.set("done", true); return false end
    pcall(function() Zy.Script.runTask("vision_try") end)
    Zy.Script.tick({ handlers = handlers, wait_ms = 300 })
    if Zy.Script.get("done") then return false end
    return true
  end)

  local fin = Zy.Script.get("last_phase") or Zy.Game.phase(BID)
  pcall(function()
    Zy.File.write(Zy.File.varDir() .. "/.ziyan_ai_last_run.txt",
      string.format("goal=%s phase=%s done=%s\n", Zy.Script.get("goal"), tostring(fin), tostring(Zy.Script.get("done"))))
  end)
  ailog("AI generated script finished phase=" .. tostring(fin))
end

return main
